#include "engine/scripting/IVisualScriptRuntime.hpp"
#include <cassert>
int main(){engine::scripting::VisualScriptGraph graph;std::string e;assert(graph.register_node_type({"event", "Event", "", {}, {}} ,&e));auto id=graph.add_node({0,"event",{}, {}});auto runtime=engine::scripting::create_visual_script_runtime();assert(runtime->load(graph,e));engine::scripting::PinValue value;value.type=engine::scripting::PinType::Int;value.intVal=42;assert(runtime->set_variable("answer",value,e));assert(runtime->variable("answer")->intVal==42);assert(runtime->add_breakpoint({id,true},e));assert(runtime->emit_event("tick",{},e));assert(runtime->step(1,e));assert(runtime->paused());assert(runtime->remove_breakpoint(id));assert(runtime->resume(e));assert(runtime->profile().steps>=1);return 0;}
